sys_variable_value.value:
(function execute(inputs, outputs) {
    // Days of this time card already sent to Xero, read from the tracking table.
    // Same format as the old Get Time Entries output: YYYY-MM-DD, comma separated.
    var dates = [];
    var sync = new GlideRecord('x_snc_spm_xero_i_0_xero_time_entry_sync');
    sync.addQuery('time_card', inputs.time_card_sysid);
    sync.addQuery('status', 'sent');
    sync.query();
    while (sync.next()) {
        dates.push(sync.getValue('date'));
    }
    outputs.existing_dates = dates.join(',');
})(inputs, outputs);

